101	    /// Return the emitted code.
102	    pub fn finalize(mut self, loc: Option<SourceLoc>) -> MachBufferFinalized<Final> {
103	        let constants = Default::default();
104	        let stencil = self
105	            .buffer
106	            .finish(&constants, self.emit_state.ctrl_plane_mut());
107	        stencil.apply_base_srcloc(loc.unwrap_or_default())
108	    }
